// CWMacApp.pch.h// Copyright © 1993-2000 by Apple Computer, Inc.  All rights reserved.////	Generates the 'MacAppHeaders<xxx>' precompiled header for Metrowerks C/C++./*	Change History		12/21/00	Move include of ansi_prefix so it is included only when precompiling					or if not using precompiled headers. This prevents a compile error					in wchar_t.h because ansi_prefix.win32.h was including it before the 					precompiled header was included. 		06/30/99	Profiler support. 		03/24/99	Update copyright notice.		03/19/99	[W] Pull in the right ansi_prefix for Windows.		03/10/99	Target file naming changes.		02/03/99	[C] Fix Carbon and OSX header names.		10/26/98	Added precompiled hdrs for Mach-0 (Carbon) __MACH__*/#ifndef __CWMACAPP_PCH_H__#define __CWMACAPP_PCH_H__#pragma once on#pragma check_header_flags on#ifndef	MSL_USE_PRECOMPILED_HEADERS #define MSL_USE_PRECOMPILED_HEADERS	0	/* We supply our own in MacApp */#endif#if __option(precompile)	#if __MWERKS__ >= 0x2100		// slightly larger but much faster generation of pch files		#pragma faster_pch_gen on	#endif	#ifndef __ansi_prefix__		#if __INTEL__			#define NOMINMAX			#include <ansi_prefix.win32.h>		#else			#include <ansi_prefix.mac.h>		#endif	#endif 	// Always include required headers	#ifndef __MacAppRequired__	#include "MacAppRequired.h"	#endif	// =========================================================	// Precompile Sources Flag	// =========================================================	// By default, this is set to ACS's precompile setting,.	//	// You can control this flag independently of ACS by defining it	// in either AutoSwitches_AC.h or MacAppAutoSwitches.h which is	// included in MacAppRequired.h above.	#ifndef qPrecompileMacApp	#	ifdef qPrecompile_AC	#		define qPrecompileMacApp 			qPrecompile_AC	#	else	#		define qPrecompileMacApp			1	#	endif	#endif	#if qPrecompileMacApp		#include "MacApp.h"   		#include "MAToolboxHeaders.h"	#endif		//	Support for automatically naming the precompiled header file ...	//		#if __MACH__		#if wantDebugging			#pragma precompile_target "MacAppHeaders_osx_d"		#else			#pragma precompile_target "MacAppHeaders_osx_n"		#endif	#elif __CARBON__		#if wantDebugging			#pragma precompile_target "MacAppHeaders_car_d"		#else			#pragma precompile_target "MacAppHeaders_car_n"		#endif	#elif __CFM68K__		#if wantDebugging			#pragma precompile_target "MacAppHeadersCFM68K_d"		#elif __profile__			#pragma precompile_target "MacAppHeadersCFM68K_profile"		#else			#pragma precompile_target "MacAppHeadersCFM68K_nd"		#endif	#elif __MC68K__		#if wantDebugging			#pragma precompile_target "MacAppHeaders_68k_d"		#elif __profile__			#pragma precompile_target "MacAppHeaders_68k_profile"		#else			#pragma precompile_target "MacAppHeaders_68k_n"		#endif	#elif __POWERPC__		#if wantDebugging			#pragma precompile_target "MacAppHeaders_ppc_d"		#elif __profile__			#pragma precompile_target "MacAppHeaders_ppc_profile"		#else			#pragma precompile_target "MacAppHeaders_ppc_n"		#endif	#elif __INTEL__		#if wantDebugging			#pragma precompile_target "MacAppHeaders_win_d"		#else			#pragma precompile_target "MacAppHeaders_win_n"		#endif	#else		#error "target currently unsupported"	#endif#else	#if __MACH__		#if wantDebugging			#include "MacAppHeaders_osx_d"		#else			#include "MacAppHeaders_osx_n"		#endif	#elif __CARBON__		#if wantDebugging			#include "MacAppHeaders_car_d"		#else			#include "MacAppHeaders_car_n"		#endif	#elif __CFM68K__		#if wantDebugging			#include "MacAppHeadersCFM68K_d"		#elif __profile__			#include "MacAppHeadersCFM68K_profile"		#else			#include "MacAppHeadersCFM68K_n"		#endif	#elif __MC68K__		#if wantDebugging			#include "MacAppHeaders_68k_d"		#elif __profile__			#include "MacAppHeaders_68k_profile"		#else			#include "MacAppHeaders_68k_n"		#endif	#elif __POWERPC__		#if wantDebugging			#include "MacAppHeaders_ppc_d"		#elif __profile__			#include "MacAppHeaders_ppc_profile"		#else			#include "MacAppHeaders_ppc_n"		#endif	#elif __INTEL__		#if wantDebugging			#include "MacAppHeaders_win_d"		#else			#include "MacAppHeaders_win_n"		#endif	#else		#error "target currently unsupported"	#endif#endif#endif//----------------------------------------------------------------------------------------// End of CWMacApp.pch.h/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		----- R10 -----		 3/22/96	Switch to including CWMacAppHeaders.h*/